// Get webhook data from the Webhook node
const webhookData = $('Webhook').first().json;
const body = webhookData.body || webhookData;

// Get issues from current input (SQL results)
const issues = $input.all();

console.log('📊 Building context:', {
  manuscriptId: body.manuscriptId,
  chapterNumber: body.chapterNumber,
  issueCount: issues.length
});

// Format Sam's issues for context
const issuesText = issues.length > 0 
  ? issues.map((item, index) => {
      const issue = item.json;
      return `${index + 1}. [${issue.element_type}] "${issue.quoted_text}"
   Issue: ${issue.issue_description}
   Your suggestion: ${issue.editor_suggestion}`;
    }).join('\n\n')
  : 'No issues flagged yet for this chapter.';

// Check if this is a "Discuss" button click
const isNoteDiscussion = !!body.issueId;

console.log('Context details:', {
  isNoteDiscussion,
  issueCount: issues.length,
  hasContext: !!body.context
});

// Build the context object
const context = {
  manuscriptTitle: body.context?.manuscriptTitle || body.manuscriptTitle || 'Untitled',
  chapterNumber: body.chapterNumber || body.context?.chapterNumber,
  chapterTitle: body.context?.chapterTitle || body.chapterTitle || 'Chapter ' + body.chapterNumber,
  chapterContent: body.context?.chapterContent || body.chapterContent || '',
  samIssues: issuesText,
  authorMessage: body.message,
  authorFirstName: body.authorFirstName || 'there',
  isNoteDiscussion: isNoteDiscussion
};

// If discussing a specific issue, add that context
if (isNoteDiscussion && issues.length > 0) {
  const specificIssue = issues.find(item => item.json.id === body.issueId);

  if (specificIssue) {
    context.discussingIssue = {
      category: specificIssue.json.element_type,
      quotedText: specificIssue.json.quoted_text,
      issue: specificIssue.json.issue_description,
      suggestion: specificIssue.json.editor_suggestion
    };

    console.log('✅ Found specific issue for discussion:', context.discussingIssue.category);
  }
}

console.log('✅ Context built successfully');

return { json: context };

const context = $json;

// Build the prompt based on whether it's a discussion
let prompt = `MANUSCRIPT: "${context.manuscriptTitle}"
CHAPTER: ${context.chapterNumber} - "${context.chapterTitle}"

YOUR FLAGGED ISSUES FOR THIS CHAPTER:
${context.samIssues}

CHAPTER EXCERPT:
${context.chapterContent}

---

`;

if (context.isNoteDiscussion && context.discussingIssue) {
  prompt += `DISCUSSION CONTEXT:
The author clicked "Discuss" on one of your editorial notes. Here's what you flagged:

Category: ${context.discussingIssue.category}
Quoted Text: "${context.discussingIssue.quotedText}"
Your Note: ${context.discussingIssue.issue}
Your Suggestion: ${context.discussingIssue.suggestion}

The author is asking: "${context.authorMessage}"

Explain your thinking about this note naturally - walk them through your editorial reasoning.`;
} else {
  prompt += `AUTHOR'S MESSAGE:
${context.authorMessage}

Respond as Sam would - specific, enthusiastic, and focused on prose craft.`;
}

return {
  json: {
    prompt: prompt
  }
};

const cellReturn = $input.first().json;

let responseText = '';
let terminalReason = null;

if (cellReturn.ok) {
  responseText = cellReturn.content || '';
} else {
  terminalReason = cellReturn.terminal_reason || 'unknown';
  if (terminalReason === 'max_tokens_truncation') {
    responseText = 'That response ran long — could you ask a more focused question?';
  } else if (terminalReason === 'validation_failed') {
    responseText = 'Sorry, something went wrong on my end. Please try again.';
  } else {
    responseText = "I'm having trouble connecting right now. Try again in a moment.";
  }
}

return [{ json: {
  ok: !!cellReturn.ok,
  response: responseText,
  cell_terminal_reason: terminalReason,
  cell_model: cellReturn.model || null,
  cell_input_tokens: cellReturn.input_tokens || null,
  cell_output_tokens: cellReturn.output_tokens || null,
  cell_latency_ms: cellReturn.latency_ms || null,
  cell_cost_usd: cellReturn.cost_estimate_usd || null
}}];

